define("local_gerenciamentomatriculas/bulk_enrolment_processor",["core/ajax"],function(Ajax){"use strict";var methodName="local_gerenciamentomatriculas_enrol_user_batch",chunkValues=function(values,size){var chunks=[];for(var offset=0;offset<values.length;offset+=size){chunks.push(values.slice(offset,offset+size))}return chunks},appendStudentResult=function(container,student,result,strings){var details=document.createElement("details");details.className="mb-2";var summary=document.createElement("summary");summary.textContent=student.name+" — "+strings.success+": "+result.success.length+"; "+strings.skipped+": "+result.skipped.length+"; "+strings.errors+": "+result.errors.length;details.append(summary);[[strings.success,result.success],[strings.skipped,result.skipped],[strings.errors,result.errors]].forEach(function(entry){var label=entry[0],messages=entry[1];if(!messages.length){return}var heading=document.createElement("strong");heading.textContent=label;details.append(heading);var list=document.createElement("ul");messages.forEach(function(message){var item=document.createElement("li");item.textContent=message;list.append(item)});details.append(list)});container.append(details)};return{init:function(buttonId,progressId,statusId,resultsId,completionActionsId,students,courseIds,chunkSize,strings){var button=document.getElementById(buttonId),progress=document.getElementById(progressId),status=document.getElementById(statusId),results=document.getElementById(resultsId),completionActions=document.getElementById(completionActionsId),normalizedStudents=students.map(function(student){return{id:parseInt(student.id,10),name:String(student.name)}}).filter(function(student){return Number.isInteger(student.id)&&student.id>0}),normalizedCourses=Array.from(new Set(courseIds.map(Number).filter(Number.isInteger))),safeChunkSize=Math.max(1,parseInt(chunkSize,10)||1);if(!button||!progress||!status||!results||!normalizedStudents.length||!normalizedCourses.length){return}button.disabled=false;button.addEventListener("click",async function(){button.disabled=true;results.replaceChildren();var total=normalizedStudents.length*normalizedCourses.length,processed=0,transportFailed=false;progress.max=total;progress.value=0;progress.classList.remove("d-none");status.textContent=strings.processing+" 0/"+total+". "+strings.keepopen;var preventNavigation=function(event){event.preventDefault();event.returnValue=""};window.addEventListener("beforeunload",preventNavigation);try{studentLoop:for(var student of normalizedStudents){var studentResult={success:[],skipped:[],errors:[]};for(var courseChunk of chunkValues(normalizedCourses,safeChunkSize)){try{var response=await Ajax.call([{methodname:methodName,args:{userid:student.id,courseids:courseChunk}}])[0];studentResult.success.push.apply(studentResult.success,response.success||[]);studentResult.skipped.push.apply(studentResult.skipped,response.skipped||[]);studentResult.errors.push.apply(studentResult.errors,response.errors||[])}catch(error){studentResult.errors.push(strings.transporterror);transportFailed=true}processed+=courseChunk.length;progress.value=processed;status.textContent=strings.processing+" "+processed+"/"+total+". "+strings.keepopen;if(transportFailed){appendStudentResult(results,student,studentResult,strings);break studentLoop}}appendStudentResult(results,student,studentResult,strings)}}finally{window.removeEventListener("beforeunload",preventNavigation)}status.textContent=transportFailed?strings.interrupted:strings.completed+" "+processed+"/"+total+".";if(completionActions){completionActions.classList.remove("d-none")}},{once:true})}}});
